import{initNotifications,tasksChanged}from'./notifications.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];const KEY='dock-tasks-v1';let tasks=[];try{const data=JSON.parse(localStorage.getItem(KEY)||'[]');if(Array.isArray(data))tasks=data.filter(t=>t&&typeof t.id==='string'&&typeof t.title==='string')}catch{}let filter='all',query='',sort='newest',editing=null;const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const today=()=>{const d=new Date();return`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
function notify(text,undo){const el=$('#toast');el.textContent=text;if(undo){const b=document.createElement('button');b.textContent='Undo';b.onclick=()=>{undo();el.classList.remove('show')};el.append(b)}el.classList.add('show');clearTimeout(notify.timer);notify.timer=setTimeout(()=>el.classList.remove('show'),6500)}
function save(){try{localStorage.setItem(KEY,JSON.stringify(tasks))}catch{notify('Storage unavailable. Export a backup before closing this page.')}render();tasksChanged()}
function reset(){filter='all';query='';$('#task-search').value='';render()}
function render(){const done=tasks.filter(t=>t.status==='done').length;$('#summary').textContent=tasks.length?`${tasks.length-done} active · ${done} completed`:'Capture your first task below.';$('#clear-done').disabled=!done;$$('[data-filter]').forEach(b=>b.classList.toggle('active',b.dataset.filter===filter));const list=tasks.filter(t=>(filter==='all'||filter==='done'&&t.status==='done'||filter==='active'&&t.status!=='done'||filter==='today'&&t.status!=='done'&&t.due&&t.due<=today())&&`${t.title} ${t.notes||''}`.toLowerCase().includes(query.toLowerCase()));const rank={high:0,normal:1,low:2};list.sort((a,b)=>sort==='priority'?(rank[a.priority]??1)-(rank[b.priority]??1)||b.created-a.created:sort==='due'?(a.due||'9999').localeCompare(b.due||'9999')||b.created-a.created:b.created-a.created);$('#task-list').innerHTML=list.map(t=>`<article class="task-row ${t.status==='done'?'done':''}" data-id="${esc(t.id)}"><button class="complete-task" data-complete="${esc(t.id)}" aria-label="${t.status==='done'?'Reopen':'Complete'} ${esc(t.title)}" aria-pressed="${t.status==='done'}">${t.status==='done'?'✓':''}</button><div class="task-content"><button class="task-name" data-edit="${esc(t.id)}">${esc(t.title)}</button><div class="task-meta">${t.priority==='high'?'<span class="priority-high">High priority</span>':t.priority==='low'?'<span>Low priority</span>':''}${t.due?`<span class="${t.due<today()&&t.status!=='done'?'overdue':''}">${t.due<today()&&t.status!=='done'?'Overdue · ':''}${esc(t.due)}</span>`:''}${t.remindAt?`<span>Reminder · ${esc(new Date(t.remindAt).toLocaleString(undefined,{dateStyle:'short',timeStyle:'short'}))}</span>`:''}${t.notes?'<span>Has notes</span>':''}</div></div><select class="task-state" data-state="${esc(t.id)}" aria-label="Status for ${esc(t.title)}">${[['todo','To do'],['doing','In progress'],['done','Done']].map(([v,label])=>`<option value="${v}" ${t.status===v?'selected':''}>${label}</option>`).join('')}</select><button class="edit-task-button" data-edit="${esc(t.id)}" aria-label="Edit ${esc(t.title)}">Edit</button></article>`).join('')+(list.length?'':`<div class="empty"><p>${!tasks.length?'A clear space for your next step.':query?'No tasks match your search.':filter==='today'?'Nothing due today or overdue.':filter==='done'?'Completed tasks will appear here.':'No active tasks. Nice work.'}</p><button class="secondary" id="empty-action">${!tasks.length?'Add your first task':'Show all tasks'}</button></div>`);if($('#empty-action'))$('#empty-action').onclick=()=>{if(!tasks.length)$('#task-title').focus();else reset()};$$('[data-complete]').forEach(b=>b.onclick=()=>{const t=tasks.find(t=>t.id===b.dataset.complete);t.status=t.status==='done'?'todo':'done';save()});$$('[data-state]').forEach(s=>s.onchange=()=>{tasks.find(t=>t.id===s.dataset.state).status=s.value;save()});$$('[data-edit]').forEach(b=>b.onclick=()=>edit(b.dataset.edit))}
function edit(id){editing=id;const t=tasks.find(t=>t.id===id),f=$('#edit-task');for(const key of ['title','status','priority','due','notes'])f.elements[key].value=t[key]||'';const time=t.remindAt?new Date(t.remindAt):null;f.elements.reminder.value=time?`${time.getFullYear()}-${String(time.getMonth()+1).padStart(2,'0')}-${String(time.getDate()).padStart(2,'0')}T${String(time.getHours()).padStart(2,'0')}:${String(time.getMinutes()).padStart(2,'0')}`:'';$('#task-dialog').showModal()}
$('#quick-add').onsubmit=e=>{e.preventDefault();const title=$('#task-title').value.trim();if(!title)return;if(tasks.length>=500){notify('This list has 500 tasks. Export a backup and clear completed tasks.');return}tasks.push({id:crypto.randomUUID(),title,notes:'',status:'todo',priority:'normal',due:'',created:Date.now()});$('#task-title').value='';filter='all';query='';$('#task-search').value='';save();$('#task-title').focus()};$('#edit-task').onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));data.title=data.title.trim();if(!data.title)return;const old=tasks.find(t=>t.id===editing);const remindAt=data.reminder?new Date(data.reminder).getTime():null;delete data.reminder;if(remindAt&&(!Number.isFinite(remindAt)||remindAt>Date.now()+366*86400000||remindAt<Date.now()&&Math.abs(remindAt-(old.remindAt||0))>60000)){notify('Choose a future reminder time within the next year.');return}data.remindAt=remindAt;Object.assign(tasks.find(t=>t.id===editing),data);save();$('#task-dialog').close();notify('Task saved')};for(const id of ['close-edit','cancel-edit'])$('#'+id).onclick=()=>$('#task-dialog').close();$('#delete-task').onclick=()=>{const removed=tasks.find(t=>t.id===editing);tasks=tasks.filter(t=>t.id!==editing);$('#task-dialog').close();save();notify('Task deleted',()=>{if(!tasks.some(t=>t.id===removed.id))tasks.push(removed);save()})};$('#clear-done').onclick=()=>{const removed=tasks.filter(t=>t.status==='done');tasks=tasks.filter(t=>t.status!=='done');save();notify(`${removed.length} completed tasks cleared`,()=>{const ids=new Set(tasks.map(t=>t.id));tasks.push(...removed.filter(t=>!ids.has(t.id)));save()})};$$('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;render()});$('#task-search').oninput=e=>{query=e.target.value;render()};$('#task-sort').onchange=e=>{sort=e.target.value;render()};$('#toggle-theme').onclick=()=>{const dark=!document.documentElement.classList.contains('dark');document.documentElement.classList.toggle('dark',dark);try{const s=JSON.parse(localStorage.getItem('dock-v1')||'{}');s.theme=dark?'dark':'light';localStorage.setItem('dock-v1',JSON.stringify(s))}catch{notify('Theme could not be saved.')}};
$('#export-tasks').onclick=()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify({version:1,tasks},null,2)],{type:'application/json'}));a.download='dock-tasks.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};$('#import-tasks').onclick=()=>$('#import-file').click();$('#import-file').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>4000000)throw Error();const data=JSON.parse(await file.text());if(data.version!==1||!Array.isArray(data.tasks)||data.tasks.length>500)throw Error();const ids=new Set();for(const t of data.tasks){if(!t||typeof t.id!=='string'||ids.has(t.id)||typeof t.title!=='string'||!t.title.trim()||t.title.length>200||!['todo','doing','done'].includes(t.status)||!['high','normal','low'].includes(t.priority)||typeof t.notes!=='string'||t.notes.length>5000||typeof t.due!=='string'||t.due&&!/^\d{4}-\d{2}-\d{2}$/.test(t.due)||!Number.isFinite(t.created))throw Error();if(t.remindAt!=null&&!Number.isFinite(t.remindAt))throw Error();ids.add(t.id)}const existing=new Set(tasks.map(t=>t.id));const added=data.tasks.filter(t=>!existing.has(t.id));if(tasks.length+added.length>500)throw Error();tasks.push(...added);reset();save();notify(`Imported ${added.length} new tasks; existing tasks were kept.`)}catch{notify('Choose a valid Tasks backup (up to 500 tasks).')}finally{e.target.value=''}};render();

initNotifications(()=>tasks);
